/**
 * Kruitbosch Detail Service — Fetches enriched product detail data from kruitbosch_products table.
 *
 * Returns fields not exposed in the unified SupplierOffer shape:
 * - color (nullable)
 * - vatRateBasisPoints
 * - fullDescription (nullable, maps to description column)
 */

import { eq } from 'drizzle-orm'
import { db } from '@/db/index.js'
import { kruitboschProducts } from '@/db/schema.js'

/** Enriched Kruitbosch product detail response shape */
export interface KruitboschDetailResponse {
  eanUpc: string
  color: string | null
  vatRateBasisPoints: number
  fullDescription: string | null
}

/**
 * Fetch detailed product information for a Kruitbosch product by EAN.
 * Returns null if the product is not found in the local catalog.
 */
export async function getKruitboschDetail(ean: string): Promise<KruitboschDetailResponse | null> {
  const trimmedEan = ean.trim()

  const results = await db.select({
    eanUpc: kruitboschProducts.eanUpc,
    color: kruitboschProducts.color,
    vatRateBasisPoints: kruitboschProducts.vatRateBasisPoints,
    fullDescription: kruitboschProducts.description,
  })
    .from(kruitboschProducts)
    .where(eq(kruitboschProducts.eanUpc, trimmedEan))

  if (results.length === 0) {
    return null
  }

  const row = results[0]

  return {
    eanUpc: row.eanUpc,
    color: row.color ?? null,
    vatRateBasisPoints: row.vatRateBasisPoints,
    fullDescription: row.fullDescription ?? null,
  }
}

