// ── Detail view types ─────────────────────────────────────────────────────

/** Enriched product detail returned by per-supplier detail endpoints */
export interface ProductDetail {
  eanUpc: string
  status?: 'ACTIVE' | 'OBSOLETE'
  minimumOrderAmount?: number
  unitsInPackaging?: number
  netWeight?: number | null
  grossWeight?: number | null
  keywordDescription?: string
  productGroupDescription?: string
  vatRate?: string
  longDescription?: string
  color?: string | null
  vatRateBasisPoints?: number
  fullDescription?: string | null
  category?: string | null
  _cacheVersion?: 'nested' | 'flat'
}

/** Field definition for rendering a detail card */
export interface DetailFieldConfig {
  /** Key in the ProductDetail object */
  key: keyof ProductDetail
  /** Human-readable label shown above the value */
  label: string
  /** CSS class override for the value display (e.g. 'badge', 'price-highlight') */
  variant?: 'default' | 'badge' | 'price-highlight' | 'weight'
  /** Custom render function — overrides default rendering */
  render?: (value: unknown, detail: ProductDetail) => React.ReactNode
  /** Whether this field should only show when it has a non-null/non-empty value */
  conditional?: boolean
}

/**
 * ExpandableRow — Wraps a table row with expand/collapse behavior.
 *
 * Manages its own expanded/loading/error state internally. Calls onRowToggle
 * when expansion changes so parent (SearchResultsTable) can track all expanded
 * EANs for pagination reset logic.
 *
 * Supports keyboard Enter/Space toggle, focus management (focus stays on trigger),
 * and Import button event propagation stop.
 *
 * Renders DetailCardGrid with supplier-specific field configurations in the
 * expanded section.
 */

import { useState, useCallback, useRef } from 'react'
import type { ProductDetail } from '../types.js'
import { DetailCardGrid } from './DetailCardGrid.js'
import type { DetailFieldConfig } from '../types.js'

// ── Supplier-specific field configurations ────────────────────────────────

/** Kruitbosch detail fields — color badge, VAT rate info, full description */
const KRUITBOSCH_FIELDS: DetailFieldConfig[] = [
  { key: 'color', label: 'Color', variant: 'badge', conditional: true },
  { key: 'vatRateBasisPoints' as keyof ProductDetail, label: 'VAT Rate (basis points)', render: (value) => {
    const bp = typeof value === 'number' ? value : parseInt(String(value ?? ''), 10)
    if (isNaN(bp)) return <span className="text-muted-foreground">—</span>
    return <span className="font-medium">{bp / 100}% ({bp} bps)</span>
  }, conditional: true },
  { key: 'fullDescription' as keyof ProductDetail, label: 'Full Description', render: (value) => {
    if (!value || String(value).trim() === '') return <span className="text-muted-foreground">—</span>
    return <p className="leading-relaxed whitespace-pre-wrap">{String(value)}</p>
  }, conditional: true }
]

/** Gransier detail fields — color badge, VAT rate info, full description */
const GRANSIER_FIELDS: DetailFieldConfig[] = [
  { key: 'color', label: 'Color', variant: 'badge', conditional: true },
  { key: 'vatRateBasisPoints' as keyof ProductDetail, label: 'VAT Rate (basis points)', render: (value) => {
    const bp = typeof value === 'number' ? value : parseInt(String(value ?? ''), 10)
    if (isNaN(bp)) return <span className="text-muted-foreground">—</span>
    return <span className="font-medium">{bp / 100}% ({bp} bps)</span>
  }, conditional: true },
  { key: 'fullDescription' as keyof ProductDetail, label: 'Full Description', render: (value) => {
    if (!value || String(value).trim() === '') return <span className="text-muted-foreground">—</span>
    return <p className="leading-relaxed whitespace-pre-wrap">{String(value)}</p>
  }, conditional: true }
]

/** DST detail fields — status, packaging, weight, classification */
const DST_FIELDS: DetailFieldConfig[] = [
  { key: 'status', label: 'Status', variant: 'badge' },
  { key: 'minimumOrderAmount', label: 'Minimum Order Amount' },
  { key: 'unitsInPackaging', label: 'Units in Packaging' },
  { key: 'netWeight', label: 'Net Weight (kg)', variant: 'weight' },
  { key: 'grossWeight', label: 'Gross Weight (kg)', variant: 'weight' },
  { key: 'keywordDescription', label: 'Classification' },
  { key: 'productGroupDescription', label: 'Product Group' },
  { key: 'vatRate', label: 'VAT Rate' },
  { key: 'longDescription', label: 'Long Description' }
]

interface ExpandableRowProps {
  /** The row content to render as the clickable trigger */
  children: React.ReactNode
  /** Unique EAN identifier for this row (used for detail fetching) */
  ean: string
  /** Async function that fetches product detail data by EAN */
  fetchDetail: (ean: string) => Promise<ProductDetail>
  /** Callback when Import button is clicked */
  onImport?: (ean: string) => void
  /** Supplier name — used to select the correct field configuration for rendering */
  supplierName?: string
}

export function ExpandableRow({ children: rowContent, ean, fetchDetail, onImport, supplierName }: ExpandableRowProps) {
  const [expanded, setExpanded] = useState(false)
  const [detail, setDetail] = useState<ProductDetail | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  // Track whether we've already fetched detail to avoid redundant calls
  const hasFetchedRef = useRef(false)

  const fetchAndSetDetail = useCallback(async (targetEan: string) => {
    setLoading(true)
    setError(null)
    try {
      const result = await fetchDetail(targetEan)
      setDetail(result)
      hasFetchedRef.current = true
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)))
    } finally {
      setLoading(false)
    }
  }, [fetchDetail, hasFetchedRef])

  const handleToggle = useCallback(() => {
    if (!expanded) {
      setExpanded(true)
      // Fetch detail only on first expansion
      if (!hasFetchedRef.current) {
        void fetchAndSetDetail(ean)
      }
    } else {
      setExpanded(false)
    }
  }, [expanded, ean, hasFetchedRef, fetchAndSetDetail])

  const handleRetry = useCallback(() => {
    void fetchAndSetDetail(ean)
  }, [ean, fetchAndSetDetail])

  const handleImportClick = useCallback((e: React.MouseEvent) => {
    // Stop propagation so clicking Import doesn't trigger row expansion
    e.stopPropagation()
    onImport?.(ean)
  }, [onImport, ean])

  // Select field configuration based on supplier
  const fields = supplierName === 'Gransier'
    ? GRANSIER_FIELDS
    : supplierName === 'Kruitbosch'
      ? KRUITBOSCH_FIELDS
      : DST_FIELDS

  return (
    <>
      {/* Trigger row */}
      <tr
        onClick={handleToggle}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleToggle() } }}
        tabIndex={0}
        role="row"
        aria-expanded={expanded}
        className={`border-b hover:bg-muted/20 transition-colors cursor-pointer ${expanded ? 'bg-muted/30 expanded-row' : ''}`}
      >
        {rowContent}
        <td className="px-4 py-2 text-center">
          <button
            onClick={handleImportClick}
            disabled={loading}
            className="px-3 py-1 text-xs font-medium bg-primary text-primary-foreground rounded hover:bg-primary/90 disabled:opacity-50 transition-colors"
          >
            Import
          </button>
        </td>
      </tr>

      {/* Expanded detail section */}
      {expanded && (
        <tr className="border-b">
          <td colSpan={11} className="px-4 py-3 bg-muted/10">
            {loading && !error && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <svg
                  className="animate-spin h-4 w-4"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
                  />
                </svg>
                <span>Loading details...</span>
              </div>
            )}

            {error && (
              <div className="flex items-center gap-3 p-3 bg-red-50 border border-red-200 rounded-md text-sm">
                <span className="text-red-700 font-medium">Error loading details</span>
                <button
                  onClick={(e) => { e.stopPropagation(); handleRetry() }}
                  className="px-3 py-1 text-xs font-medium bg-red-600 text-white rounded hover:bg-red-700 transition-colors"
                >
                  Retry
                </button>
              </div>
            )}

            {!loading && !error && detail && (
              <DetailCardGrid detail={detail} fields={fields} />
            )}
          </td>
        </tr>
      )}
    </>
  )
}

/**
 * DST Detail Service — Fetches enriched product detail data from supplier_products table.
 *
 * Reads the full nested `DstProductRaw` JSON tree stored in `raw_json` and extracts:
 * - status (ACTIVE / OBSOLETE)
 * - minimumOrderAmount, unitsInPackaging
 * - netWeight, grossWeight
 * - keywordDescription, productGroupDescription
 * - vatRate, longDescription
 *
 * Handles legacy flat cache entries gracefully — returns whatever fields are available
 * from the flat shape without errors. A re-search automatically upgrades to nested format.
 */

import { eq } from 'drizzle-orm'
import { db } from '@/db/index.js'
import { supplierProducts } from '@/db/schema.js'
import type { DstDataNode, DstOfferRaw } from '../../../types.js'

// ============================================================================
// Response types
// ============================================================================

/** Enriched DST product detail response shape */
export interface DstDetailResponse {
  eanUpc: string
  status?: 'ACTIVE' | 'OBSOLETE'
  minimumOrderAmount?: number
  unitsInPackaging?: number
  netWeight: number | null
  grossWeight: number | null
  keywordDescription?: string
  productGroupDescription?: string
  vatRate?: string
  longDescription?: string
  _cacheVersion: 'nested' | 'flat'
}

// ============================================================================
// Nested JSON extraction (new format)
// ============================================================================

/** Extract detail fields from a nested DstProductRaw structure. */
function extractFromNested(data: DstDataNode): Omit<DstDetailResponse, 'eanUpc' | '_cacheVersion'> {
  const orderInfo = data.orderinformation
  const productInfo = data.productinformation
  const classification = data.productclassification

  return {
    status: (orderInfo?.status as 'ACTIVE' | 'OBSOLETE') || undefined,
    minimumOrderAmount: orderInfo?.minimum_orderamount ?? undefined,
    unitsInPackaging: orderInfo?.units_in_packaging ?? undefined,
    netWeight: productInfo?.physical_specifications?.net_weight ?? null,
    grossWeight: productInfo?.physical_specifications?.gross_weight ?? null,
    keywordDescription: classification?.keyword_description || undefined,
    productGroupDescription: classification?.productgroup_description || undefined,
    vatRate: productInfo?.price_information?.vat || undefined,
    longDescription: productInfo?.descriptions?.long_description || undefined
  }
}

// ============================================================================
// Flat JSON extraction (legacy format — graceful degradation)
// ============================================================================

/** Extract whatever fields are available from a flat DstOfferRaw structure. */
function extractFromFlat(_offer: DstOfferRaw): Omit<DstDetailResponse, 'eanUpc' | '_cacheVersion'> {
  // Flat format doesn't have status, weight, classification — return null/undefined
  return {
    netWeight: null,
    grossWeight: null
  }
}

// ============================================================================
// Detection & parsing
// ============================================================================

/** Check if raw JSON is in the new nested format (has `data.content` or `data.identifiers`). */
function isNestedFormat(rawJson: string): boolean {
  try {
    const parsed = JSON.parse(rawJson) as Record<string, unknown>
    // Nested format has a top-level `data` key with identifiers inside
    return typeof parsed.data === 'object' && parsed.data !== null &&
           typeof (parsed.data as Record<string, unknown>).identifiers === 'object'
  } catch {
    return false
  }
}

// ============================================================================
// Main service function
// ============================================================================

/**
 * Fetch detailed product information for a DST product by EAN.
 * Returns null if the product is not found in the supplier_products table.
 *
 * Handles both nested (new) and flat (legacy) JSON formats:
 * - Nested format: full DstProductRaw tree → rich detail extraction
 * - Flat format: legacy DstOfferRaw → graceful degradation with available fields only
 */
export async function getDstDetail(ean: string): Promise<DstDetailResponse | null> {
  const trimmedEan = ean.trim()

  const results = await db.select({
    rawJson: supplierProducts.rawJson,
    eanUpc: supplierProducts.eanUpc
  })
    .from(supplierProducts)
    .where(eq(supplierProducts.eanUpc, trimmedEan))

  if (results.length === 0) {
    return null
  }

  const row = results[0]

  try {
    // Detect format and extract accordingly
    if (isNestedFormat(row.rawJson)) {
      const parsed = JSON.parse(row.rawJson) as Record<string, unknown>
      const dataNode = parsed.data as DstDataNode

      return {
        eanUpc: row.eanUpc,
        ...extractFromNested(dataNode),
        _cacheVersion: 'nested'
      }
    } else {
      // Legacy flat format — graceful degradation
      const offer = JSON.parse(row.rawJson) as DstOfferRaw

      return {
        eanUpc: row.eanUpc,
        ...extractFromFlat(offer),
        _cacheVersion: 'flat'
      }
    }
  } catch (err) {
    console.error('[DST Detail Service] Failed to parse cached JSON for EAN:', trimmedEan, err instanceof Error ? err.message : String(err))
    // Return minimal response on parse failure — don't crash the endpoint
    return {
      eanUpc: row.eanUpc,
      netWeight: null,
      grossWeight: null,
      _cacheVersion: 'flat'
    }
  }
}

