import { kruitboschProducts } from '@/db/schema.js'
import { getKruitboschDetail } from '../detail-service.js'

describe('Kruitbosch Detail Service — getKruitboschDetail', () => {
  beforeEach(async () => {
    // Clean up any leftover test data
    await db.delete(kruitboschProducts)
  })

  it('returns detail data when product is found by EAN', async () => {
    // Insert a test product
    await db.insert(kruitboschProducts).values({
      id: 'test-kp-1',
      eanUpc: '8712345678901',
      name: 'Test Product',
      sellPriceNet: 1000,
      vatRateBasisPoints: 2100,
      color: 'Rood',
      description: 'Full product description text here'
    })

    const result = await getKruitboschDetail('8712345678901')

    expect(result).toEqual({
      eanUpc: '8712345678901',
      color: 'Rood',
      vatRateBasisPoints: 2100,
      fullDescription: 'Full product description text here'
    })
  })

  it('returns null when EAN not found in kruitbosch_products table', async () => {
    const result = await getKruitboschDetail('0000000000000')

    expect(result).toBeNull()
  })

  it('trims whitespace from EAN before querying', async () => {
    // Insert a test product
    await db.insert(kruitboschProducts).values({
      id: 'test-kp-2',
      eanUpc: '8712345678902',
      name: 'Test Product 2',
      sellPriceNet: 2000,
      vatRateBasisPoints: 900,
      color: 'Blauw',
      description: 'Another description'
    })

    // Query with leading/trailing whitespace
    const result = await getKruitboschDetail(' 8712345678902 ')

    expect(result).not.toBeNull()
    expect(result!.eanUpc).toBe('8712345678902')
  })

  it('handles nullable fields correctly — color is null', async () => {
    // Insert a test product with no color or description
    await db.insert(kruitboschProducts).values({
      id: 'test-kp-3',
      eanUpc: '8712345678903',
      name: 'Test Product 3',
      sellPriceNet: 3000,
      vatRateBasisPoints: 2100,
      color: null,
      description: null
    })

    const result = await getKruitboschDetail('8712345678903')

    expect(result).toEqual({
      eanUpc: '8712345678903',
      color: null,
      vatRateBasisPoints: 2100,
      fullDescription: null
    })
  })

  it('handles missing description field gracefully (undefined → null)', async () => {
    // Insert a test product with no description column set
    await db.insert(kruitboschProducts).values({
      id: 'test-kp-4',
      eanUpc: '8712345678904',
      name: 'Test Product 4',
      sellPriceNet: 4000,
      vatRateBasisPoints: 900,
      color: 'Groen'
    })

    const result = await getKruitboschDetail('8712345678904')

    expect(result).toEqual({
      eanUpc: '8712345678904',
      color: 'Groen',
      vatRateBasisPoints: 900,
      fullDescription: null
    })
  })
})

