export async function fetchKruitboschDetail(ean: string): Promise<ProductDetail> {
  const response = await fetch(
    `${BASE_URL}/api/product-finder/kruitbosch/detail?ean=${encodeURIComponent(ean)}`
  )

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Detail fetch failed: ${response.status}`)
  }

  return response.json() as Promise<ProductDetail>
